    http_response_code(403);$error=__t('Invalid or already-used code, or too many attempts.','کُد نادرست یا قبلاً استفاده شده است، یا تلاش‌ها بیشتر از حد مجاز است.','کوډ ناسم یا کارول شوی دی.');
