?><!doctype html><html lang="<?= sanitize(get_current_lang()) ?>" dir="<?= get_current_dir() ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= __t('Verify central access','تأیید مدیریت مرکزی','مرکزي لاسرسی تایید') ?></title><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/style.css"><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/workflow.css"><main class="card modern-form" style="max-width:440px;margin:10vh auto"><h1><?= __t('Two-step verification','تأیید دومرحله‌ای','دوه پړاوه تایید') ?></h1><p><?= __t('Enter the six-digit code from your authenticator app.','کُد شش‌رقمی برنامهٔ تأییدکنندهٔ خود را بنویسید.','د تایید اپ شپږ شمېریز کوډ ولیکئ.') ?></p><?php if(!totp_secret((int)auth_user()['id'])):?><p role="alert"><?= __t('Second-factor setup is required on the host. Central access remains blocked.','تنظیم عامل دوم در هاست لازم است؛ دفتر دو تا آن وقت بسته می‌ماند.','دویم عامل په کوربه کې تنظیم کړئ.') ?></p><?php endif ?><p role="alert"><?= sanitize($error) ?></p><form method="post"><?= csrf_field() ?><label for="code"><?= __t('Verification code','کُد تأیید','د تایید کوډ') ?></label><input id="code" name="code" class="form-control" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus><label style="display:flex;gap:8px;margin:14px 0"><input type="checkbox" name="trust_device" value="1"> <?= __t('Trust this device for 30 days','این دستگاه برای ۳۰ روز مورد اعتماد باشد','دا وسیله د ۳۰ ورځو لپاره باوري وي') ?></label><button type="submit" class="btn btn-primary"><?= __t('Verify','تأیید','تایید') ?></button></form></main></html>
